package com.mamtrex.hospital.billing;
import com.mamtrex.hospital.audit.AuditService; import com.mamtrex.hospital.shared.NotFoundException; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/invoices") public class InvoiceController { private final InvoiceRepository repo; private final AuditService audit; public InvoiceController(InvoiceRepository r,AuditService a){repo=r;audit=a;} public record Request(@jakarta.validation.constraints.NotBlank String patientId, @jakarta.validation.constraints.NotBlank String invoiceNumber, @jakarta.validation.constraints.NotBlank String amount, @jakarta.validation.constraints.NotBlank String currency, @jakarta.validation.constraints.NotBlank String status){} @PostMapping public Invoice create(@Valid @RequestBody Request r){var e=repo.save(new Invoice(r.patientId(), r.invoiceNumber(), r.amount(), r.currency(), r.status()));audit.record("CREATE","Invoice",e.getId().toString(),"created");return e;} @GetMapping public List<Invoice> list(){return repo.findAll();} @GetMapping("/{id}") public Invoice get(@PathVariable UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("Invoice not found: "+id));} @DeleteMapping("/{id}") public void delete(@PathVariable UUID id){if(!repo.existsById(id))throw new NotFoundException("Invoice not found: "+id);repo.deleteById(id);audit.record("DELETE","Invoice",id.toString(),"deleted");} }
